"""Build the folder-local research map from saved evidence."""
import json,pathlib,html
p=pathlib.Path(__file__).resolve().parents[1]
r=json.loads((p/'data/results.json').read_text())
nodes=[dict(id='audit',kind='theorem',tier='T2',status='established',title='Corollary 7.2 follows at named-theorem boundary',statement='Conditional on OpenAI 1.1 and GSW 4.16, Corollary 7.2 follows.',where=['GSW-CHAIN.md'],review={'state':'unreviewed'}),dict(id='surface',kind='theorem',tier='T2',status='established',title='Rooted surface cardinality obstruction',statement='The domain exceeds the codomain by 2g.',where=['PROOFS.md'],review={'state':'unreviewed'}),dict(id='torus',kind='evidence',tier='T4',status='computed',title='Heawood root-free polynomial vanishes',statement='All 24 state coefficients vanish.',evidence=['data/torus_signs.json']),dict(id='direct',kind='question',tier=None,status='open',title='Direct nonplanar states proof',statement='Find a sign and target retaining topology needed for connectedness.',next='Test homology-sensitive weights on the saved Heawood embedding.')]
(p/'knowledge.json').write_text(json.dumps({'schema':1,'meta':{'title':'Pfaffian route'},'nodes':nodes},indent=2))
frontier={'scope':'Named examples only; no exhaustive graph-order census','examples':[{'name':g['name'],'order':g['n'],'pfaffian':g['pfaffian'],'P4_verified':not g['bad_paths'],'tier':'T4'} for g in r['graphs']]}
(p/'frontier.json').write_text(json.dumps(frontier,indent=2))
(p/'sota.json').write_text(json.dumps({'scope':'Local proposal for coordinator, not canonical repository state','questions':[{'question':'Corollary dependency','best':'FOLLOWS relative to accepted named theorems','where':'GSW-CHAIN.md','review':'unreviewed','previous':['GSW source unopened']},{'question':'Direct states route','best':'Literal candidates obstructed; general route open','where':'DIRECT-ROUTE.md','review':'unreviewed','previous':[]}]},indent=2))
rows=''.join('<tr><td>'+html.escape(g['name'])+'</td><td>'+str(g['n'])+'</td><td>'+str(g['pfaffian'])+'</td><td>'+str(g['hamiltonian_cycles'])+'</td><td>'+str(len(g['bad_paths']))+'</td></tr>' for g in r['graphs'])
(p/'dashboard.html').write_text('<!doctype html><meta charset="utf-8"><title>Pfaffian route research</title><h1>Pfaffian route</h1><p>Local research record. All new proofs unreviewed; counts T4.</p><p>Audit closed relative to named theorems. Direct states route remains open.</p><table border="1"><tr><th>Named example</th><th>Order</th><th>Pfaffian signing</th><th>Hamiltonian cycles</th><th>Uncovered P4 paths</th></tr>'+rows+'</table><p><a href="REPORT.md">Report</a> | <a href="DIRECT-ROUTE.md">Failed routes and open doors</a> | <a href="PROOFS.md">Proofs</a></p>')
assert all((p/f).exists() for f in ['REPORT.md','GSW-CHAIN.md','DIRECT-ROUTE.md','PROOFS.md','data/results.json'])
print('Local map built; required deliverables present.')
